import {useObjectWrapper} from '@github-ui/workspace-editor/hooks/use-object-wrapper'
import type {EditorProps, Monaco} from '@monaco-editor/react'
import {loader} from '@monaco-editor/react'
import {clsx} from 'clsx'
import type {editor, IDisposable, Uri} from 'monaco-editor'
import {useCallback, useEffect, useRef, useState} from 'react'

import {useEditorContext} from '../contexts/EditorContext'
import {useFileSyncerContext} from '../contexts/FileSyncerContext'
import {useAgentStatus} from '../contexts/WorkbenchStoreContext'
import {executeEdits} from '../monaco/execute-edits'
import {getOrCreateModel, noop} from '../monaco/get-or-create-model'
import {tokenizeFile} from '../monaco/tokenize-file'
import usePrevious from '../monaco/use-previous'
import workbenchConsole from '../utilities/console'
import {type EditorEdit, getDiffLines, getEditorEdits} from '../utilities/get-diff-lines'
import styles from './MonacoEditor.module.css'

const DEFAULT_VIEW_STATES = new Map<string, editor.ICodeEditorViewState>()
const DEFAULT_OPTIONS = {}
const DEFAULT_OVERRIDE_SERVICES = {}
const DEFAULT_WRAPPER_PROPS = {}

const FADED_OUT_TO_EDITS_DELAY = 1000
const LINE_BY_LINE_ANIMATION_DELAY = 30

// Minimap decorations only support hex color codes so they are defined inside the tsx
// https://github.com/microsoft/monaco-editor/issues/4178
// From var(--bgColor-attention-muted)
const EDIT_HIGHLIGHT_LIGHT_COLOR = '#fff8c5'
// From var(--bgColor-neutral-emphasis)
const EDIT_HIGHLIGHT_DARK_COLOR = '#656c76'
// From var(--diffBlob-additionLine-bgColor)
const EDIT_HIGHLIGHT_INSERT_LIGHT_COLOR = '#dafbe1'
const EDIT_HIGHLIGHT_INSERT_DARK_COLOR = '#2ea04326'
// From var(--diffBlob-deletionLine-bgColor)
const EDIT_HIGHLIGHT_DELETE_LIGHT_COLOR = '#ffebe9'
const EDIT_HIGHLIGHT_DELETE_DARK_COLOR = '#f851491a'
// From var(--bgColor-accent-emphasis)
const EDIT_HIGHLIGHT_DIFF_LIGHT_COLOR = '#0969da'
const EDIT_HIGHLIGHT_DIFF_DARK_COLOR = '#1f6feb'
// From var(--bgColor-default)
const FADED_LIGHT_COLOR = '#ffffff'
const FADED_DARK_COLOR = '#0d1117'
const MINIMAP_LINE_HEIGHT = 2 // Approximate line height in minimap lines

export type MonacoEditorProps = Omit<EditorProps, 'onValidate'> & {
  options?: editor.IStandaloneEditorConstructionOptions & {
    /*
     * shouldDiffChanges: Compare current value with the value in the editor
     * and highlight the changes
     * @default false
     */
    shouldDiffChanges?: boolean
    /*
     * isStaleContent: Fades out the content of the editor when the file is stale
     */
    isStaleContent?: boolean
  }
  onValidate?: (monaco: Monaco, uri: Uri, markers: editor.IMarker[]) => void
  viewStates?: Map<string, editor.ICodeEditorViewState>
}

export function MonacoEditor({
  defaultValue,
  defaultLanguage,
  defaultPath,
  value,
  language,
  path,
  /* === */
  theme = 'light',
  line,
  loading = 'Loading...',
  options: {shouldDiffChanges, isStaleContent, ...options} = DEFAULT_OPTIONS,
  overrideServices = DEFAULT_OVERRIDE_SERVICES,
  saveViewState = true,
  viewStates = DEFAULT_VIEW_STATES,
  // keepCurrentModel = false,
  /* === */
  width = '100%',
  height = '100%',
  className,
  wrapperProps = DEFAULT_WRAPPER_PROPS,
  /* === */
  beforeMount = noop,
  onMount = noop,
  onChange,
  onValidate = noop,
}: MonacoEditorProps) {
  const {setIsAnimating, isAnimating, setHasInitializedModelValue, hasInitializedModelValue} = useEditorContext()
  const {fileContentsRef, setFileContentsRef} = useFileSyncerContext()
  const {isAgentBusy} = useAgentStatus()
  const previousIsAgentBusy = usePrevious(isAgentBusy)

  const [isEditorReady, setIsEditorReady] = useState(false)
  const [isMonacoMounting, setIsMonacoMounting] = useState(true)

  const monacoRef = useRef<Monaco | null>(null)
  const editorRef = useRef<editor.IStandaloneCodeEditor | null>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const onMountRef = useRef(onMount)
  const beforeMountRef = useRef(beforeMount)
  const subscriptionRef = useRef<IDisposable | undefined>(undefined)
  const preventCreationRef = useRef(false)
  const preventTriggerChangeEventRef = useRef<boolean>(false)

  const animationTimeoutsRef = useRef<number[]>([])
  const fadedDecorationCollectionRef = useRef<Map<number, editor.IEditorDecorationsCollection[]>>(new Map())
  const animationDecorationsCollectionRef = useRef<editor.IEditorDecorationsCollection[]>([])
  const fileDecorationsCollectionRef = useRef<editor.IEditorDecorationsCollection[]>([])
  const minimapOverlayRef = useRef<HTMLElement | null>(null)
  const fileViewZonesRef = useRef<string[]>([])
  const isStaleRef = useRef(false)
  const currentPath = useObjectWrapper(path)

  // Run initializeMonaco only on mount and dispose only for cleanup
  useEffect(() => {
    const cancelable = loader.init()

    const initializeMonaco = async () => {
      try {
        const monaco = await cancelable
        monacoRef.current = monaco
        setIsMonacoMounting(false)
      } catch (err: unknown) {
        if ((err as {type: string} | undefined)?.type !== 'cancelation') {
          workbenchConsole.error('Failed to initialize Monaco Editor:', err)
        }
      }
    }

    initializeMonaco()

    return () => {
      // Cancel load if still in progress
      if (!editorRef.current) {
        cancelable.cancel()
        return
      }

      // Dispose editor if it exists
      subscriptionRef.current?.dispose()
      editorRef.current.getModel()?.dispose()
      editorRef.current.dispose()
    }
  }, [])

  useEffect(() => {
    const animationTimeouts = animationTimeoutsRef.current
    return () => {
      // Clear any pending animation timeouts on unmount
      for (const timeoutId of animationTimeouts) {
        window.clearTimeout(timeoutId)
        setIsAnimating(false)
      }
    }
  }, [setIsAnimating])

  // Iterate through all faded decoration collections and clear them
  const clearAllFadedDecorations = useCallback(() => {
    if (fadedDecorationCollectionRef.current) {
      for (const [_, decorationCollections] of fadedDecorationCollectionRef.current) {
        for (const collection of decorationCollections) {
          collection.clear()
        }
      }
      fadedDecorationCollectionRef.current.clear()
    }

    // Clear minimap overlay
    if (minimapOverlayRef.current) {
      minimapOverlayRef.current.remove()
      minimapOverlayRef.current = null
      if (containerRef.current) {
        const minimapContainer = containerRef.current.querySelector('.minimap') as HTMLElement
        if (minimapContainer) {
          const orphanedOverlays = minimapContainer.querySelectorAll('.minimap-overlay')
          for (const overlay of orphanedOverlays) {
            overlay.remove()
          }
        }
      }
    }
  }, [])

  const clearAnimationDecorations = useCallback(() => {
    if (animationDecorationsCollectionRef.current) {
      for (const collection of animationDecorationsCollectionRef.current) {
        collection.clear()
      }
      animationDecorationsCollectionRef.current = []
    }
  }, [])

  const clearAllFileDecorations = useCallback(() => {
    if (fileDecorationsCollectionRef.current) {
      for (const collection of fileDecorationsCollectionRef.current) {
        collection.clear()
      }
      fileDecorationsCollectionRef.current = []
    }
  }, [])

  const clearFileViewZones = useCallback(() => {
    if (!editorRef.current) return

    editorRef.current.changeViewZones(changeAccessor => {
      for (const viewZoneId of fileViewZonesRef.current) {
        changeAccessor.removeZone(viewZoneId)
      }
    })
    fileViewZonesRef.current = []
  }, [])

  const resetAnimations = useCallback(() => {
    clearAnimationDecorations()
    const animationTimeouts = animationTimeoutsRef.current
    for (const timeoutId of animationTimeouts) {
      window.clearTimeout(timeoutId)
      setIsAnimating(false)
    }
  }, [clearAnimationDecorations, setIsAnimating])

  // Reset file when the model changes
  const resetFile = useCallback(() => {
    clearAllFadedDecorations()
    clearAllFileDecorations()
    clearFileViewZones()
    resetAnimations()
  }, [clearAllFadedDecorations, clearAllFileDecorations, clearFileViewZones, resetAnimations])

  // If we just finished fetching, clear all editor decorations
  useEffect(() => {
    if (previousIsAgentBusy && !isAgentBusy) {
      resetFile()
    }
  }, [isAgentBusy, previousIsAgentBusy, resetFile])

  /**
   * Adds a faded out rectangle overlay to the minimap
   * @param startLineNumber - The line number to begin fading out until the bottom of the minimap
   */
  const fadeMinimap = useCallback((startLineNumber: number) => {
    if (!containerRef.current) return

    const minimaps = containerRef.current.querySelectorAll('.minimap')
    const minimapContainer = containerRef.current.querySelectorAll('.minimap')[
      minimaps.length - 1
    ] as HTMLElement | null // Multiple minimap classes in the DOM can exist, so we take the last one
    if (!minimapContainer) return

    if (!minimapOverlayRef.current) {
      const currentTheme = (editorRef.current as unknown as {_themeService: {_theme: {themeName: string}}})
        ?._themeService?._theme?.themeName

      const newOverlay = document.createElement('div')
      newOverlay.className = `${styles.minimapOverlay} minimap-overlay` // Add a unique class for detection
      newOverlay.style.backgroundColor = currentTheme === 'github-dark' ? FADED_DARK_COLOR : FADED_LIGHT_COLOR
      minimapContainer.style.position = 'relative'
      minimapContainer.appendChild(newOverlay)
      minimapOverlayRef.current = newOverlay
    }

    const overlay = minimapOverlayRef.current
    if (!editorRef.current) return
    const model = editorRef.current.getModel()
    if (!model) return

    const totalLines = model.getLineCount()
    if (startLineNumber >= totalLines) return

    const startHeight = MINIMAP_LINE_HEIGHT * startLineNumber
    const overlayHeight = Math.max(0, MINIMAP_LINE_HEIGHT * (totalLines - startLineNumber))

    Object.assign(overlay.style, {
      top: `${startHeight}px`,
      height: `${overlayHeight}px`,
    })
  }, [])

  const fadeContent = useCallback(() => {
    if (!editorRef.current || !monacoRef.current) return null

    const model = editorRef.current.getModel()
    if (!model) return null

    // Add to map of startLineNumber to an array of decoration collections
    const collection = fadedDecorationCollectionRef.current
    // Grey out entire page
    const lineCount = model.getLineCount() || 0
    for (let i = 1; i <= lineCount; i++) {
      const editCollection = editorRef.current.createDecorationsCollection([
        {
          range: new monacoRef.current.Range(i, 1, i, 1),
          options: {
            isWholeLine: true,
            className: styles.editFaded,
          },
        },
      ])

      // Get existing collections for this line or create a new array
      const existingCollections = collection.get(i) || []
      existingCollections.push(editCollection)
      collection.set(i, existingCollections)
    }

    fadedDecorationCollectionRef.current = collection
    fadeMinimap(0)
  }, [fadeMinimap])

  const highlightInsertionLines = useCallback((lineNumbers: number[], currentDeletedLines: Set<number>) => {
    if (!editorRef.current || !monacoRef.current) return null

    const model = editorRef.current.getModel()
    if (!model) return null
    const decorations = lineNumbers.map(lineNumber => ({
      range: new monacoRef.current!.Range(lineNumber, 1, lineNumber, 1),
      options: {
        isWholeLine: true,
        className: styles.editHighlightInsert,
        minimap: {
          position: 2,
          color: currentDeletedLines.has(lineNumber)
            ? EDIT_HIGHLIGHT_DIFF_LIGHT_COLOR
            : EDIT_HIGHLIGHT_INSERT_LIGHT_COLOR,
          darkColor: currentDeletedLines.has(lineNumber)
            ? EDIT_HIGHLIGHT_DIFF_DARK_COLOR
            : EDIT_HIGHLIGHT_INSERT_DARK_COLOR,
        },
      },
    }))

    const decorationCollection = editorRef.current.createDecorationsCollection(decorations)
    fileDecorationsCollectionRef.current = [...fileDecorationsCollectionRef.current, decorationCollection]
  }, [])

  const showDeletionLines = useCallback(
    (lineNumber: number, heightInLines: number, text?: string | null) => {
      if (!editorRef.current || !monacoRef.current) return null

      const model = editorRef.current.getModel()
      if (!model) return null
      const decorations = [
        {
          range: new monacoRef.current.Range(lineNumber, 1, lineNumber, 1),
          options: {
            minimap: {
              position: 2,
              color: EDIT_HIGHLIGHT_DELETE_LIGHT_COLOR,
              darkColor: EDIT_HIGHLIGHT_DELETE_DARK_COLOR,
            },
          },
        },
      ]

      const decorationCollection = editorRef.current.createDecorationsCollection(decorations)
      fileDecorationsCollectionRef.current = [...fileDecorationsCollectionRef.current, decorationCollection]

      editorRef.current.changeViewZones(changeAccessor => {
        const domNode = document.createElement('div')

        const viewZoneId = changeAccessor.addZone({
          afterLineNumber: lineNumber - 1, // Show above the line number that was deleted
          heightInLines,
          domNode,
        })

        fileViewZonesRef.current.push(viewZoneId)

        // Create the embedded editor AFTER the view zone is added
        setTimeout(() => {
          // Make sure the DOM node is attached
          if (domNode.parentElement && monacoRef.current) {
            // Embeds a smaller, read-only Monaco editor to handle tokenization and coloring
            monacoRef.current.editor.create(domNode, {
              value: text || '',
              ...options,
              language,
              theme,
              extraEditorClassName: styles.deletionEditor,
              // Hide all unnecessary UI elements
              readOnly: true,
              scrollBeyondLastLine: false,
              scrollbar: {
                vertical: 'hidden',
                horizontal: 'hidden',
              },
              minimap: {
                enabled: false,
              },
              lineNumbers: 'off',
              glyphMargin: false,
              folding: false,
              lineDecorationsWidth: 0,
              lineNumbersMinChars: 0,
              overviewRulerBorder: false,
              overviewRulerLanes: 0,
              hideCursorInOverviewRuler: true,
              contextmenu: false,
              links: false,
              quickSuggestions: false,
              suggestOnTriggerCharacters: false,
              acceptSuggestionOnEnter: 'off',
              tabCompletion: 'off',
              wordBasedSuggestions: 'off',
              parameterHints: {
                enabled: false,
              },
              hover: {
                enabled: false,
              },
              // Remove selector and padding
              selectOnLineNumbers: false,
              selectionHighlight: false,
              renderLineHighlight: 'none',
              cursorBlinking: 'solid',
              cursorStyle: 'line',
              insertSpaces: true,
              wordWrap: 'off',
              automaticLayout: true,
              // Remove padding and margins
              padding: {
                top: 0,
                bottom: 0,
              },
              // Disable selection capabilities
              readOnlyMessage: {
                value: '',
              },
              domReadOnly: true,
              // Additional options to minimize UI
              renderControlCharacters: false,
              renderWhitespace: 'none',
              showFoldingControls: 'never',
              matchBrackets: 'never',
              smoothScrolling: false,
              cursorSmoothCaretAnimation: 'off',
            })
          }
        }, 0)
      })
    },
    [language, options, theme],
  )

  const highlightEditedLines = useCallback((lineNumbers: number[]) => {
    if (!editorRef.current || !monacoRef.current) return null

    const model = editorRef.current.getModel()
    if (!model) return null
    const currentTheme = (editorRef.current as unknown as {_themeService: {_theme: {themeName: string}}})?._themeService
      ?._theme?.themeName
    const decorations = lineNumbers.map(lineNumber => ({
      range: new monacoRef.current!.Range(lineNumber, 1, lineNumber, 1),
      options: {
        isWholeLine: true,
        className: currentTheme === 'github-dark' ? styles.editHighlightDark : styles.editHighlightLight,
        marginClassName: currentTheme === 'github-dark' ? styles.editHighlightDark : styles.editHighlightLight,
        minimap: {
          position: 1,
          color: EDIT_HIGHLIGHT_LIGHT_COLOR,
          darkColor: EDIT_HIGHLIGHT_DARK_COLOR,
        },
      },
    }))

    const decorationCollection = editorRef.current.createDecorationsCollection(decorations)
    animationDecorationsCollectionRef.current = [...animationDecorationsCollectionRef.current, decorationCollection]

    // Automatically remove the decorations after animation completes
    const timeoutId = window.setTimeout(() => {
      if (editorRef.current) {
        decorationCollection.clear()
      }
    }, LINE_BY_LINE_ANIMATION_DELAY)

    animationTimeoutsRef.current.push(timeoutId)

    return decorationCollection
  }, [])

  // Function to apply edits one by one with animation
  const applyEditSequentially = useCallback(
    (updatedValue: string, edits: EditorEdit[], cursor: number) => {
      setIsAnimating(true)

      if (!editorRef.current) return

      // Check if no longer fetching - if so, apply all remaining edits at once
      if (!isAgentBusy) {
        if (edits.length > 0) {
          const model = editorRef.current.getModel()
          if (model) {
            executeEdits(editorRef.current, model, edits)
          }
        }

        preventTriggerChangeEventRef.current = false
        resetFile()
        setIsAnimating(false)
        return
      }

      // No edits or finished all edits
      const [nextEdit, ...remainingEdits] = edits
      if (edits.length === 0 || !nextEdit) {
        preventTriggerChangeEventRef.current = false
        clearAllFadedDecorations()
        clearFileViewZones()

        // Get delta of original file to display diffs
        const originalFileContent =
          (currentPath.current && fileContentsRef.current?.[currentPath.current]?.content) || ''
        const diffEdits = getEditorEdits(getDiffLines(originalFileContent, editorRef.current.getValue()))

        // Display diff decorations
        const currentDeletedLines = new Set<number>()
        for (const edit of diffEdits) {
          const {startLineNumber, endLineNumber} = edit.highlightRange
          switch (edit.operation) {
            case 'INSERTION': {
              // If the original file is empty, highlight all lines
              if (originalFileContent === '') {
                const lineCount = editorRef.current.getModel()?.getLineCount()
                if (lineCount) {
                  const allLines = Array.from({length: lineCount}, (_, i) => i + 1)
                  highlightInsertionLines(allLines, currentDeletedLines)
                  break
                }
              }

              // Highlight all the numbers that were inserted
              const insertedLines = []
              for (let lineNum = startLineNumber; lineNum <= endLineNumber; lineNum++) {
                insertedLines.push(lineNum)
              }
              highlightInsertionLines(insertedLines, currentDeletedLines)
              break
            }
            case 'DELETION': {
              const heightInLines = endLineNumber - startLineNumber + 1
              showDeletionLines(startLineNumber, heightInLines, edit.originalText)
              currentDeletedLines.add(startLineNumber)
              break
            }
            default:
              break
          }
        }

        // Reveal the first edited range to make it visible
        editorRef.current.revealLines(
          diffEdits[0]?.highlightRange.startLineNumber || 1,
          diffEdits[0]?.highlightRange.endLineNumber || 1,
          0,
        )

        setIsAnimating(false)
        return
      }

      const timeoutId = window.setTimeout(() => {
        if (!editorRef.current) return
        const model = editorRef.current.getModel()
        if (!model) return

        const groupedEdits: EditorEdit[] = [nextEdit]
        const affectedLines = new Set<number>()

        // Move the cursor line by line if there is no edit
        if (nextEdit.range.startLineNumber > cursor) {
          const decorationCollections = fadedDecorationCollectionRef.current.get(cursor) || []
          for (const collection of decorationCollections) {
            collection.clear()
          }
          fadedDecorationCollectionRef.current.delete(cursor)
          highlightEditedLines([cursor])
          affectedLines.add(cursor)
        } else {
          // Get all affected line numbers for this nextEdit
          for (let aLine = nextEdit.range.startLineNumber; aLine <= nextEdit.range.endLineNumber; aLine++) {
            affectedLines.add(aLine)
          }

          if (nextEdit.operation === 'DELETION') {
            // Get the next edits that are on the same line
            for (const edit of remainingEdits) {
              if (!affectedLines.has(edit.range.startLineNumber)) break
              groupedEdits.push(edit)
            }
          }

          // Clear faded decorations
          for (const aLine of affectedLines) {
            const decorationCollections = fadedDecorationCollectionRef.current.get(aLine) || []
            for (const collection of decorationCollections) {
              collection.clear()
            }
            fadedDecorationCollectionRef.current.delete(aLine)
          }

          highlightEditedLines(Array.from(affectedLines))

          // Apply all edits in the current group
          executeEdits(editorRef.current, model, groupedEdits)
        }
        // Update minimap overlay to exclude processed lines
        const affectedLinesArray = Array.from(affectedLines)
        const lastEditedLine = affectedLinesArray[affectedLinesArray.length - 1]
        if (lastEditedLine) fadeMinimap(lastEditedLine)

        // Because we apply edit sequentially, we re-diff the editor and value to get the new range
        const remainingEditsToApply = getEditorEdits(getDiffLines(editorRef.current.getValue(), updatedValue))
        // eslint-disable-next-line react-hooks/immutability
        applyEditSequentially(updatedValue, remainingEditsToApply, cursor + Array.from(affectedLines).length)
      }, LINE_BY_LINE_ANIMATION_DELAY)

      animationTimeoutsRef.current.push(timeoutId)
    },
    [
      clearAllFadedDecorations,
      clearFileViewZones,
      currentPath,
      fileContentsRef,
      fadeMinimap,
      highlightEditedLines,
      highlightInsertionLines,
      isAgentBusy,
      resetFile,
      setIsAnimating,
      showDeletionLines,
    ],
  )

  const handleStaleContent = useCallback(
    (shouldStale: boolean = false) => {
      if (shouldStale && !isStaleRef.current) {
        fadeContent()
        isStaleRef.current = true
      }
      if (!shouldStale && isStaleRef.current) {
        isStaleRef.current = false
      }
    },
    [fadeContent],
  )

  useEffect(() => {
    if (!isEditorReady || !editorRef.current || value === undefined) return
    if (value === editorRef.current.getValue()) {
      // Monaco caches content for its models, so show faded content even when value is the same
      handleStaleContent(isStaleContent)
      return
    }

    const model = editorRef.current.getModel()
    if (!model) return

    if (shouldDiffChanges) {
      if (isAnimating) return
      const diffLines = getDiffLines(editorRef.current.getValue(), value)
      const editsToApply = getEditorEdits(diffLines)
      if (editsToApply.length === 0) return

      preventTriggerChangeEventRef.current = true
      resetAnimations()
      handleStaleContent(true)

      // Briefly display fade before beginning edits
      const timeoutId = window.setTimeout(() => {
        applyEditSequentially(value, editsToApply, 1)
      }, FADED_OUT_TO_EDITS_DELAY)
      animationTimeoutsRef.current.push(timeoutId)
      return
    }

    preventTriggerChangeEventRef.current = true
    // Set the initial model value to close the undo stack after switching files
    if (!hasInitializedModelValue) {
      editorRef.current.setValue(value)
      setHasInitializedModelValue(true)
    } else {
      executeEdits(editorRef.current, model, [
        {
          range: model.getFullModelRange(),
          text: value,
        },
      ])
    }

    tokenizeFile(model)
    handleStaleContent(isStaleContent)

    preventTriggerChangeEventRef.current = false
  }, [
    applyEditSequentially,
    handleStaleContent,
    hasInitializedModelValue,
    isAnimating,
    isEditorReady,
    isStaleContent,
    resetAnimations,
    setHasInitializedModelValue,
    shouldDiffChanges,
    value,
  ])

  // Jump to line number
  useEffect(() => {
    if (!isEditorReady) return

    // reason for undefined check: https://github.com/suren-atoyan/monaco-react/pull/188
    if (line !== undefined) {
      editorRef.current?.revealLine(line)
    }
  }, [line, isEditorReady])

  // Change path
  useEffect(() => {
    if (!isEditorReady) return
    if (!editorRef.current) return

    const newPath = path || defaultPath || ''
    const cachedFileState = fileContentsRef.current?.[newPath]
    let cachedValue = null
    if (saveViewState && cachedFileState) {
      cachedValue = cachedFileState.content
    }

    const model = getOrCreateModel(
      monacoRef.current!,
      cachedValue || defaultValue || value || '',
      defaultLanguage || language || '',
      newPath,
    )

    const currentModel = editorRef.current?.getModel()
    if (model !== currentModel) {
      // Cache the current view state before switching models
      const previousPath = currentModel?.uri.path?.replace(/^\//, '')
      if (saveViewState && previousPath) {
        const serializedViewState = editorRef.current?.saveViewState()
        const savedFileState = fileContentsRef.current?.[previousPath]
        if (serializedViewState) viewStates.set(previousPath, serializedViewState)
        setFileContentsRef({
          ...(fileContentsRef.current || {}),
          [previousPath]: {
            ...(savedFileState || {
              fileName: previousPath,
            }),
            content: value,
          },
        })
      }

      // Reset view for new model
      setHasInitializedModelValue(false)
      resetFile()

      // Switch models
      editorRef.current?.setModel(model)

      // Restore the view state for the new model
      const savedViewState = viewStates.get(newPath)
      if (saveViewState) {
        if (savedViewState) editorRef.current?.restoreViewState(savedViewState)
        if (cachedValue) setHasInitializedModelValue(true)
      }
    }
  }, [
    defaultLanguage,
    defaultPath,
    defaultValue,
    fileContentsRef,
    isEditorReady,
    language,
    path,
    resetFile,
    saveViewState,
    setFileContentsRef,
    setHasInitializedModelValue,
    value,
    viewStates,
  ])

  // Change options
  useEffect(() => {
    if (!isEditorReady) return
    editorRef.current?.updateOptions(options)
  }, [isEditorReady, options])

  // Change language
  useEffect(() => {
    if (!isEditorReady) return
    const model = editorRef.current?.getModel()
    if (model && language) monacoRef.current?.editor.setModelLanguage(model, language)
  }, [isEditorReady, language])

  // Change theme
  useEffect(() => {
    if (!isEditorReady) return
    monacoRef.current?.editor.setTheme(theme)
  }, [isEditorReady, theme])

  // onMount
  useEffect(() => {
    if (!isEditorReady) return
    onMountRef.current(editorRef.current!, monacoRef.current!)
  }, [isEditorReady])

  // onChange
  useEffect(() => {
    if (isEditorReady && onChange) {
      subscriptionRef.current?.dispose()
      subscriptionRef.current = editorRef.current?.onDidChangeModelContent(event => {
        if (!preventTriggerChangeEventRef.current) {
          onChange(editorRef.current!.getValue(), event)
        }
      })
    }
  }, [isEditorReady, onChange])

  // onValidate
  useEffect(() => {
    if (!isEditorReady || !monacoRef.current) return () => {}

    const changeMarkersListener = monacoRef.current.editor.onDidChangeMarkers(uris => {
      const editorUri = editorRef.current!.getModel()?.uri

      if (editorUri && monacoRef.current) {
        const currentEditorHasMarkerChanges = uris.find(uri => uri.path === editorUri.path)
        if (currentEditorHasMarkerChanges) {
          const markers = monacoRef.current.editor.getModelMarkers({
            resource: editorUri,
          })

          onValidate?.(monacoRef.current, editorUri, markers)
        }
      }
    })

    return () => {
      changeMarkersListener?.dispose()
    }
  }, [isEditorReady, onValidate])

  const createEditor = useCallback(() => {
    if (!containerRef.current || !monacoRef.current) return
    if (!preventCreationRef.current) {
      beforeMountRef.current(monacoRef.current)
      const autoCreatedModelPath = path || defaultPath
      const defaultModel = getOrCreateModel(
        monacoRef.current,
        value || defaultValue || '',
        defaultLanguage || language || '',
        autoCreatedModelPath || '',
      )
      if (value) setHasInitializedModelValue(true)

      editorRef.current = monacoRef.current?.editor.create(
        containerRef.current,
        {
          model: defaultModel,
          automaticLayout: true,
          ...options,
        },
        overrideServices,
      )

      if (autoCreatedModelPath) {
        const savedViewState = viewStates.get(autoCreatedModelPath)
        if (saveViewState && savedViewState) {
          editorRef.current.restoreViewState(savedViewState)
        }
      }

      monacoRef.current.editor.setTheme(theme)

      if (line !== undefined) {
        editorRef.current.revealLine(line)
      }

      const model = editorRef.current.getModel()
      if (model) tokenizeFile(model)

      setIsEditorReady(true)
      preventCreationRef.current = true
    }
  }, [
    path,
    defaultPath,
    value,
    defaultValue,
    defaultLanguage,
    language,
    setHasInitializedModelValue,
    options,
    overrideServices,
    theme,
    line,
    viewStates,
    saveViewState,
  ])

  useEffect(() => {
    if (!isMonacoMounting && !isEditorReady) {
      createEditor()
    }
  }, [isMonacoMounting, isEditorReady, createEditor])

  return (
    <section className={styles.wrapper} style={{width, height}} data-testid="monaco-editor-section" {...wrapperProps}>
      {!isEditorReady && <div className={styles.loadingContainer}>{loading}</div>}
      <div
        ref={containerRef}
        className={clsx(className, styles.fullWidth, !isEditorReady && styles.hide)}
        data-testid="monaco-editor-container"
      />
    </section>
  )
}
