import {diffLines} from 'diff'
import type {editor} from 'monaco-editor'

export type Operation = 'INSERTION' | 'DELETION' | 'EQUAL'
export type DiffLine = {
  operation: Operation
} & editor.IIdentifiedSingleEditOperation
export type EditorEdit = EditorInsertion | EditorDeletion
type EditorInsertion = editor.IIdentifiedSingleEditOperation & {
  operation: 'INSERTION'
  highlightRange: HighlightRange
}
type EditorDeletion = editor.IIdentifiedSingleEditOperation & {
  operation: 'DELETION'
  text: null // Deletion edits have no text, just a range
  originalText: string | null
  highlightRange: HighlightRange
}
type HighlightRange = {
  startLineNumber: number
  endLineNumber: number
}

export function getDiffLines(oldText: string, newText: string): DiffLine[] {
  // Compares two blocks of text while accounting for line endings
  const diffs = diffLines(oldText, newText, {newlineIsToken: true})

  // Track position in the document
  let currentLine = 1
  let currentColumn = 1

  return diffs.map((part, index) => {
    let operation: Operation = 'EQUAL'
    if (part.added) operation = 'INSERTION'
    if (part.removed) operation = 'DELETION'

    // Store the starting position before processing these lines
    const startLineNumber = currentLine
    const startColumn = currentColumn

    // Ensure endLineNumber and endColumn don't exceed oldText boundaries
    if (index === diffs.length - 1 && operation === 'INSERTION') {
      return {
        operation,
        text: part.value,
        range: {
          startLineNumber,
          startColumn,
          endLineNumber: currentLine,
          endColumn: currentColumn,
        },
      }
    }

    // Normalize Windows-style line endings to Unix-style first
    const normalizedValue = part.value.replace(/\r\n/g, '\n')

    // Calculate the end position based on the text content
    const lines = normalizedValue.split('\n')

    if (lines.length > 1) {
      // Multiple lines - advance to the last line
      currentLine += lines.length - 1
      currentColumn = lines[lines.length - 1]!.length + 1
    } else {
      // Single line - advance column by text length
      currentColumn += part.value.length
    }

    return {
      operation,
      text: part.value,
      range: {
        startLineNumber,
        startColumn,
        endLineNumber: currentLine,
        endColumn: currentColumn,
      },
    }
  })
}

export function getEditorEdits(diffEdits: DiffLine[]): EditorEdit[] {
  const editsToApply: EditorEdit[] = []
  for (const [index, edit] of diffEdits.entries()) {
    const {operation, text, range} = edit
    const highlightRange = {
      startLineNumber: range.startLineNumber,
      endLineNumber: range.endLineNumber,
    }

    switch (operation) {
      case 'INSERTION':
        if (!text) break
        if (text.endsWith('\n')) {
          highlightRange.endLineNumber -= 1
        }
        if (index === diffEdits.length - 1 && operation === 'INSERTION') {
          // Handle last insertion if needed
          const lines = text.split('\n')
          highlightRange.endLineNumber += lines.length - 1
        }
        editsToApply.push({
          range,
          text,
          forceMoveMarkers: true,
          operation,
          highlightRange,
        })
        break
      case 'DELETION':
        if (text?.startsWith('\n')) {
          highlightRange.startLineNumber += 1
        }
        editsToApply.push({
          range,
          text: null,
          forceMoveMarkers: true,
          operation,
          originalText: text,
          highlightRange,
        })
        break
      case 'EQUAL':
      default:
        // no action needed if equal
        break
    }
  }
  return editsToApply
}
